/// <summary>
/// designed by AVANADE
/// </summary>
/// <returns>List</returns>
public List defaultingFields()
{
    List result = next defaultingFields();

    result.addEnd(fieldNum(SalesQuotationLine, KCS_Span));
    result.addEnd(FieldNum(SalesQuotationLine, KCS_GAEBOZ));

    return result;
}

/// <summary>
/// designed by AVANANDE
/// </summary>
/// <param name = "inventTable">InventTable</param>
/// <param name = "_searchPrice">boolean</param>
public void initFromInventTable(InventTable inventTable, boolean _searchPrice)
{
    //int64 test = salesQuotationLine.KCS_QLInternalPosition;
    next initFromInventTable(inventTable, _searchPrice);

    //test = salesQuotationLine.KCS_QLInternalPosition;

    salesQuotationLine.KCS_NotCalculated = inventTable.KCS_NotCalculated;
    if (salesQuotationLine.KCS_QLLVPosition && salesQuotationLine.KCS_QLInternalPosition > 1 && salesQuotationLine.KCS_GAEBOZ)
    {
        salesQuotationLine.salesQty = 0;
    }
    if (salesQuotationLine.KCS_QLLVPosition && salesQuotationLine.KCS_QLInternalPosition > 1)
    {
        salesQuotationLine.KCS_CRMIsAlternativeLine = salesQuotationLine::AVAfindFirstInternalPosition(salesQuotationLine.QuotationId, salesQuotationLine.KCS_QLLVPosition).KCS_CRMIsAlternativeLine;
    }

    salesQuotationLine.DeliveryDateControlType = AVASalesParameters::find().SalesQuotationNoDlvDateControl == NoYes::Yes ?  SalesDeliveryDateControlType::None : salesQuotationLine.DeliveryDateControlType;
}

/// <summary>
/// designed by AVANADE WEN
/// </summary>
/// <param name = "custQuotationTrans">CustQuotationTrans</param>
/// <param name = "copyPrecisely">boolean</param>
/// <param name = "copyPriceDisc">boolean</param>
/// <param name = "copyQty">boolean</param>
/// <param name = "qty">Qty</param>
/// <param name = "_cwQty">PdsCWInventQty</param>
void  initFromCustQuotationTrans(CustQuotationTrans custQuotationTrans,
                             boolean            copyPrecisely,
                             boolean            copyPriceDisc,
                             boolean            copyQty,
                             Qty                qty
                             , PdsCWInventQty     _cwQty
                             )
{
    next initFromCustQuotationTrans(custQuotationTrans, copyPrecisely, copyPriceDisc, copyQty, qty, _cwQty);
    salesQuotationLine fromSql;
    select firstonly fromSql where fromSql.QuotationId == custQuotationTrans.QuotationId
        && fromSql.InventTransId == custQuotationTrans.InventTransId;

    salesQuotationLine.KCS_QLLVPosition             = custQuotationTrans.KCS_QLLVPosition;
    salesQuotationLine.KCS_QLInternalPosition       = custQuotationTrans.KCS_QLInternalPosition;
    salesQuotationLine.KCS_Span                     = custQuotationTrans.KCS_Span;
    salesQuotationLine.KCS_CRMIsAlternativeLine     = custQuotationTrans.KCS_CRMIsAlternativeLine;
    salesQuotationLine.KCS_MultipleItem             = fromSql.KCS_MultipleItem;
    salesQuotationLine.KCS_NotCalculated            = custQuotationTrans.KCS_NotCalculated;
    salesQuotationLine.KCS_SonderHK                 = custQuotationTrans.KCS_SonderHK;
    salesQuotationLine.KCS_HK2                      = fromSql.KCS_HK2;
    salesQuotationLine.KCS_ModelNumber              = custQuotationTrans.KCS_ModelNumber;
    salesQuotationLine.KCS_QuotationShorttext       = custQuotationTrans.KCS_QuotationShorttext;
    salesQuotationLine.KCS_BOSSpecialPrice          = custQuotationTrans.KCS_BOSSpecialPrice;
    salesQuotationLine.KCS_QLLVPrice                = custQuotationTrans.KCS_QLLVPrice;
    salesQuotationLine.KCS_QLLVAmount               = custQuotationTrans.KCS_QLLVAmount;
    salesQuotationLine.KCS_GAEBOZ                   = custQuotationTrans.KCS_GAEBOZ;
    salesQuotationLine.KCS_GAEBExtPosNr             = fromSql.KCS_GAEBExtPosNr;
    salesQuotationLine.avapainfo                    = custQuotationTrans.AVAPAInfo;

    salesQuotationLine.AVApriceCalculation();
    salesQuotationLine.KCS_LimitUnitFactor     = salesQuotationLine.AVAcalcLimitUnitFactor();
    salesQuotationLine.KCS_LimitPrice          = salesQuotationLine.AVAcalcLimitPrice();
    salesQuotationLine.KCS_LimitPricePuffer    = salesQuotationLine.AVAcalcLimitPricePuffer();

    salesQuotationLine.kcs_priceDate           = custQuotationTrans.AVAPriceDate;
    salesQuotationLine.avaUpdateHK2();

}

/// <summary>
/// designed by AVANADE WEN
/// </summary>
/// <param name = "_salesQuotationLine">SalesQuotationLine</param>
/// <param name = "_copyPrecisely">boolean</param>
/// <param name = "_copyPriceDisc">boolean</param>
/// <param name = "_copyQty">boolean</param>
/// <param name = "_qty">Qty</param>
/// <param name = "_cwQty">PdsCWInventQty</param>
void  initFromSalesQuotationLine(SalesQuotationLine     _salesQuotationLine,
                             boolean                _copyPrecisely,
                             boolean                _copyPriceDisc,
                             boolean                _copyQty,
                             Qty                    _qty
                             , PdsCWInventQty       _cwQty
                             )
{
    next initFromSalesQuotationline(_salesQuotationLine, _copyPrecisely, _copyPriceDisc, _copyQty, _qty, _cwQty);

    SysGlobalCache globalCache = ClassFactory.globalCache();
    //RefRecId                prevLineRecId = globalCache.get(strFmt("@NDX:NXAP1P2",classStr(SalesQuotationLineType), curUserId()), 1);
    //KCS_QLLVPosition        prevLnPos = globalCache.get(strFmt("@NDX:NXAP1P2",curUserId(),classStr(SalesQuotationLineType)), 2);
    //if (!_copyPrecisely || (_copyPrecisely && prevLineRecId))
    if (!AVASalesQuotationHasLines::exist(salesQuotationLine.quotationid))
    {
        salesQuotationLine.KCS_QLLVPosition = _salesQuotationLine.KCS_QLLVPosition;
        salesQuotationLine.KCS_QLInternalPosition = _salesQuotationLine.KCS_QLInternalPosition;
    }
    if (!this.salesQuotationLine.KCS_QLLVPosition)
    {
        RefRecId                prevLineRecId = globalCache.get(strFmt("@NDX:NXAP1P2",classStr(SalesQuotationLineType), curUserId()), 1);
        KCS_QLLVPosition        prevLnPos = globalCache.get(strFmt("@NDX:NXAP1P2",curUserId(),classStr(SalesQuotationLineType)), 2);
        //KCS_QLLVPosition        prevLnPos;

        /*if (prevLnPos == '')
    {
        prevLnPos = salesQuotationLine.getLastQLLPosition();
    }*/
        salesQuotationLine      prevSql;
        if (prevLineRecId && !prevLnPos)
        {
            prevSql = salesQuotationLine::findRecId(prevLineRecId);
        }
        else if(prevLineRecId && prevLnPos)
        {
            select firstonly prevSql where prevSql.QuotationId == salesQuotationLine.QuotationId
                                    && prevSql.KCS_QLLVPosition == prevLnPos;
        }
        else if (!prevLineRecId)
        {
            if (!prevLnPos)
            {
                prevLnPos = salesQuotationLine.getLastQLLPosition();
            }
            select firstonly prevSql
        where prevSql.QuotationId == salesQuotationLine.QuotationId
        && prevSql.KCS_QLLVPosition == prevLnPos;
        }
        KCS_QLLVPosition        newLVPos;
        boolean                 adjFollowing = false;
        KCS_KBVSalesTenderLink  salesTenderLink;

        if (_salesQuotationLine.KCS_QLInternalPosition)
        {
            if (_salesQuotationLine.KCS_QLInternalPosition == 1)
            {
                //newLVPos = salesQuotationLine::KCS_getNewLVPos(_salesQuotationLine.QuotationId, prevSql.KCS_QLLVPosition);
                newLVPos = salesQuotationLine::KCS_getNewLVPos(SalesQuotationLine.quotationid, prevSql.KCS_QLLVPosition);
                globalCache.set(strFmt("@NDX:NXAP1P2",curUserId(), classStr(SalesQuotationLineType)), 2, newLVPos );
                if (salesQuotationLine::KCS_existLVPosition(salesQuotationLine.Quotationid, newLVPos))
                {
                    adjFollowing = true;
                }

            }
            else
            {
                newLVPos = globalCache.get(strFmt("@NDX:NXAP1P2", curUserId(), classStr(SalesQuotationLineType)),2);
            }

            salesQuotationLine.KCS_QLInternalPosition   = _salesQuotationLine.KCS_QLInternalPosition;
            salesQuotationLine.KCS_QLLVPosition         = newLVPos;
        }
        else
        {
            //newLVPos = salesQuotationLine::KCS_getNewLVPos(_salesQuotationLine.QuotationId, prevSql.KCS_QLLVPosition);
            newLVPos = salesQuotationLine::KCS_getNewLVPos(salesQuotationLine.QuotationId, prevSql.KCS_QLLVPosition);
            salesQuotationLine.KCS_QLLVPosition         = newLVPos;

            if (salesQuotationLine::KCS_existLVPosition(salesQuotationLine.Quotationid, salesQuotationLine.KCS_QLLVPosition))
            {
                adjFollowing = true;
            }

        }

        if (adjFollowing)
        {
            SalesQuotationLine::KCS_AdjustFollowingLVPositions(salesQuotationLine.QuotationId,salesQuotationLine.KCS_QLLVPosition,1);
        }

        salesTenderLink = KCS_KBVSalesTenderLink::find(salesQuotationLine.QuotationId);
        if (!salesTenderLink)
        {
            salesTenderLink.QuotationId = salesQuotationLine.QuotationId;
            salesTenderLink.TenderMatrix = KCS_KBVTenderIdUtility::CreateNewTenderMatrix(newLVPos,salesTenderLink.TenderMatrix);
            salesTenderLink.insert();
        }
        salesTenderLink.KCS_KBVTenderMatrixModified(SalesQuotationLine::KCS_getLastLVPosition(salesQuotationLine.Quotationid));
        salesQuotationLine.KCS_QLLVPosition   = KCS_KBVTenderIdUtility::fillMatrix(salesQuotationLine.KCS_QLLVPosition,salesTenderLink.TenderMatrix);
    }

    salesQuotationLine.KCS_Span                     = _salesQuotationLine.KCS_Span;
    salesQuotationLine.KCS_CRMIsAlternativeLine     = _salesQuotationLine.KCS_CRMIsAlternativeLine;
    //salesQuotationLine.KCS_MultipleItem             = 'X';
    //salesQuotationLine.KCS_MultipleItem             = _salesQuotationLine.KCS_MultipleItem;
    if(SalesQuotationLine::avaCountSimilarItems(salesQuotationLine.QuotationId, salesQuotationLine.ItemId) >= 1)
    {
        //this.avaAddDuplicateMark();
        salesQuotationLine.KCS_MultipleItem = 'X';
    }

    salesQuotationLine.KCS_NotCalculated            = _salesQuotationLine.KCS_NotCalculated;
    salesQuotationLine.KCS_SonderHK                 = _salesQuotationLine.KCS_SonderHK;
    salesQuotationLine.KCS_HK2                      = _salesQuotationLine.KCS_HK2;
    salesQuotationLine.KCS_ModelNumber              = _salesQuotationLine.KCS_ModelNumber;
    salesQuotationLine.KCS_QuotationShorttext       = _salesQuotationLine.KCS_QuotationShorttext;
    salesQuotationLine.KCS_BOSSpecialPrice          = _salesQuotationLine.KCS_BOSSpecialPrice;
    salesQuotationLine.KCS_QLLVPrice                = _salesQuotationLine.KCS_QLLVPrice;
    salesQuotationLine.KCS_QLLVAmount               = _salesQuotationLine.KCS_QLLVAmount;
    salesQuotationLine.KCS_GAEBOZ                   = _salesQuotationLine.KCS_GAEBOZ;
    salesQuotationLine.KCS_GAEBExtPosNr             = _salesQuotationLine.KCS_GAEBExtPosNr;
    salesQuotationLine.NDXProductName1              = _salesQuotationLine.NDXProductName1;
    salesQuotationLine.NDXProductName2              = _salesQuotationLine.NDXProductName2;
    SalesQuotationLine.KCS_calcMark                 = _salesquotationline.KCS_CalcMark;
    salesQuotationLine.AVAPAInfo                    = _salesQuotationLine.AVAPAInfo;

    //salesQuotationLine.avaAddDuplicateMark();
    salesQuotationLine.AVApriceCalculation();
    salesQuotationLine.KCS_LimitUnitFactor     = salesQuotationLine.AVAcalcLimitUnitFactor();
    salesQuotationLine.KCS_LimitPrice          = salesQuotationLine.AVAcalcLimitPrice();
    salesQuotationLine.KCS_LimitPricePuffer    = salesQuotationLine.AVAcalcLimitPricePuffer();
    globalCache.set(strFmt("@NDX:NXAP1P2",curUserId(), classStr(SalesQuotationLineType)), 2, salesQuotationLine.KCS_QLLVPosition );
}

/// <summary>
/// designed by AVANADE
/// </summary>
/// <param name = "_salesQuotationTable">SalesQuotationTable</param>
/// <param name = "_ignoreInventDim">boolean</param>
void  initFromSalesQuotationTable(SalesQuotationTable _salesQuotationTable, boolean _ignoreInventDim)
{
    next initFromSalesQuotationTable(_salesQuotationTable, _ignoreInventDim);

    salesQuotationLine.KCS_QuotationShorttext       = _salesQuotationTable.KCS_QuotationShorttext;
}

/// <summary>
/// designed from AVA
/// </summary>
public void deleted()
{
    next deleted();
    SalesQuotationLine      existedQuotationLine;

    select firstonly RecId 
        from existedQuotationLine 
        where existedQuotationLine.QuotationId == salesQuotationLine.QuotationId;

    if (!existedQuotationLine.RecId)
    {
        KCS_KBVSalesTenderLink      senderTenderLink;
        delete_from senderTenderLink
            where senderTenderLink.QuotationId == salesQuotationLine.QuotationId;
    }
}
